output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper must take the waiting cart from the entry cart bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "entry_cart_waiting": {
          "and": [
            "entry_cart_bay",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "do_not_pass_waiting_cart",
    "text": "A shopper may not walk past the entry cart bay while the entry cart is still waiting there and they are not pushing it.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "entry_cart_waiting": {
          "and": [
            "entry_cart_bay",
            "cartAt(1,5)"
          ]
        },
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "leave_entry_bay_without_cart": {
          "pre": {
            "and": [
              "entry_cart_waiting",
              "without_cart",
              "MOVE"
            ]
          },
          "post": {
            "not": "at(1,5)"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_entry_bay_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Items should not be carried by hand or picked up unless the shopper is currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_shelves",
    "text": "Product pickup interactions may occur only at recognized shelf-facing product pickup cells.",
    "abstraction": {
      "state_properties": {
        "product_pickup_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(3,2)",
            "at(5,2)",
            "at(6,2)",
            "at(2,4)",
            "at(3,4)",
            "at(5,4)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "product_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "product_pickup",
          {
            "not": "product_pickup_cell"
          }
        ]
      }
    }
  },
  {
    "id": "return_entry_cart",
    "text": "Any cart taken from the entry bay must eventually be returned to the designated return bay before exit.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "return_bay": "at(0,1)",
        "entry_cart_waiting": {
          "and": [
            "entry_cart_bay",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_entry_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_return_bay",
    "text": "A cart may be put down only in the designated return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "pedestrian_checkout_lane",
    "text": "The checkout lane and exit are pedestrian-only, so shoppers must not push carts through the bottom checkout corridor or exit while holding a cart.",
    "abstraction": {
      "state_properties": {
        "bottom_checkout_corridor": {
          "or": [
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart",
        "cart_in_checkout_corridor": {
          "and": [
            "pushing_cart",
            "bottom_checkout_corridor"
          ]
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_corridor",
          "exit_with_cart"
        ]
      }
    }
  },
  {
    "id": "redock_after_lock_tug",
    "text": "If a shopper picks up the already-returned cart at the return bay as a lock-check tug, they must put it back in the return bay before exit.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "returned_cart_available": {
          "and": [
            "return_bay",
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "returned_cart_lock_tug": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "redock_returned_cart": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returned_cart_lock_tug",
      "discharge": "redock_returned_cart"
    }
  }
]
